#!/usr/bin/env python3
"""Embed project-owned FP01 sections and installer lengths from the shared layout."""

import argparse
import hashlib
from pathlib import Path

import build_platform_patch as builder


def render_layout():
    """Render portable installer constants from the validated shared layout."""
    layout = builder.LAYOUT
    return "\n".join(
        [
            "#pragma once",
            "// Generated by tools/embed_platform_patch.py from tools/patches/platform_layout.json.",
            "#include <cstddef>",
            "namespace desk_protocol {",
            "namespace firmware_layout {",
            f"static constexpr size_t APPLICATION_SIZE = {layout['application_size']};",
            f"static constexpr size_t PAYLOAD_SIZE = {layout['payload_size']};",
            f'static constexpr const char *PAYLOAD_SIZE_TEXT = "{layout["payload_size"]} ";',
            f"static constexpr size_t ERASE_SIZE = {layout['loader_erase_size']};",
            f"static constexpr size_t DESCRIPTOR_OFFSET = {layout['descriptor_offset'] - layout['application_offset']};",
            f"static constexpr size_t DESCRIPTOR_SIZE = {layout['descriptor_size']};",
            "}  // namespace firmware_layout",
            "}  // namespace desk_protocol",
            "",
        ]
    )


def render(llvm_bin=None):
    """Compile pinned FP01 sections and render cumulative reconstruction helpers."""
    if len(builder.OUTPUT_APP_SHA256) != 64 or len(builder.PATCH_SECTIONS_SHA256) != 64:
        raise builder.ImageError(
            "FP01 image and section identities must be pinned before embedding"
        )
    sections, _ = builder.compile_patch(llvm_bin)
    offsets = {name: offset for name, (offset, _) in builder.HOOKS.items()}
    offsets.update(
        candidate=builder.CODE_OFFSET, descriptor=builder.LAYOUT["descriptor_offset"]
    )
    lines = [
        "#pragma once",
        "// Generated by tools/embed_platform_patch.py from project-owned sections.",
        "// The descriptor describes the layout; only exact full-image hashes authorize installation.",
        '#include "tb01_patch.h"',
        '#include "esphome/components/desk_uart/desk_protocol/firmware_layout.h"',
        "namespace esphome::desk_firmware_update {",
        f'static constexpr const char *FP01_SHA = "{builder.OUTPUT_APP_SHA256}";',
        "static constexpr size_t FP01_PAYLOAD_SIZE = desk_protocol::firmware_layout::PAYLOAD_SIZE;",
        'static_assert(IMAGE_SIZE == desk_protocol::firmware_layout::APPLICATION_SIZE, "FP01 readback layout mismatch");',
    ]
    for name, data in sections.items():
        lines += [
            f"// {name}: SHA-256 {hashlib.sha256(data).hexdigest()}",
            f"static constexpr uint8_t FP01_{name.upper()}[] = {{",
        ]
        for start in range(0, len(data), 16):
            lines.append(
                "  " + ",".join(f"0x{b:02x}" for b in data[start : start + 16]) + ","
            )
        lines.append("};")
    lines += ["inline uint8_t fp01_byte(size_t offset, uint8_t stock) {"]
    for name in sections:
        offset = offsets[name] - builder.APP_OFFSET
        symbol = "FP01_" + name.upper()
        lines.append(
            f"  if (offset >= 0x{offset:x} && offset < 0x{offset:x} + sizeof({symbol})) return {symbol}[offset - 0x{offset:x}];"
        )
    lines += [
        "  return rs01_byte(offset, stock);",
        "}",
        "inline bool apply_platform(uint8_t *image, size_t size) {",
        "  if (!image || size != IMAGE_SIZE) return false;",
    ]
    for name, (offset, expected) in builder.HOOKS.items():
        symbol = "before_" + name
        values = ",".join(f"0x{b:02x}" for b in expected)
        lines += [
            f"  const uint8_t {symbol}[] = {{{values}}};",
            f"  if (std::memcmp(image + 0x{offset - builder.APP_OFFSET:x}, {symbol}, sizeof({symbol}))) return false;",
        ]
    lines.append(
        f"  for (size_t i = 0x{builder.CODE_OFFSET - builder.APP_OFFSET:x}; i < IMAGE_SIZE; ++i) if (image[i] != 255) return false;"
    )
    for name in sections:
        offset = offsets[name] - builder.APP_OFFSET
        symbol = "FP01_" + name.upper()
        lines.append(
            f"  std::memcpy(image + 0x{offset:x}, {symbol}, sizeof({symbol}));"
        )
    lines += [
        "  return true;",
        "}",
        "}  // namespace esphome::desk_firmware_update",
        "",
    ]
    return "\n".join(lines)


def main():
    """Regenerate FP01 headers or reject stale checked-in output."""
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--llvm-bin", type=Path)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    outputs = {
        builder.ROOT
        / "components/desk_uart/desk_protocol/firmware_layout.h": render_layout(),
        builder.ROOT / "components/desk_firmware_update/platform_patch.h": render(
            args.llvm_bin
        ),
    }
    for output, expected in outputs.items():
        if args.check:
            if not output.is_file() or output.read_text() != expected:
                raise SystemExit(
                    f"{output.name} is stale: run tools/embed_platform_patch.py"
                )
        else:
            output.write_text(expected)


if __name__ == "__main__":
    main()
